(function(){
  'use strict';
  const {areas,exercises,schema}=window.InterviewWorkshopData,core=window.InterviewWorkshopCore,runner=window.InterviewWorkshopRunner;
  const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const key='interviewos-workshop-v1';let raw=null;try{raw=localStorage.getItem(key);}catch{}
  const state=core.parse(raw,exercises);let area=exercises.find(q=>q.id===state.selected).area,language='all',runVersion=0;
  const selected=()=>exercises.find(q=>q.id===state.selected);
  function save(){try{localStorage.setItem(key,JSON.stringify(state));$('workshop-storage').textContent='Drafts and progress saved in this browser. Localhost and Vercel have separate progress.';}catch{$('workshop-storage').textContent='Browser storage is unavailable or full. Keep a copy of your code before closing this page.';}stats();}
  function stats(){const s=core.summary(state,exercises);$('workshop-passed').textContent=`${s.passed} / ${s.total}`;$('workshop-reviewed').textContent=`${s.reviewed} / 3`;$('workshop-dashboard-stats').textContent=`${s.passed} of ${s.total} passing`;
    const next=exercises.find(q=>!core.passed(state.entries[q.id]));$('workshop-dashboard-next').textContent=next?`Next to try: ${next.title}. ${s.reviewed} of 3 code reviews completed.`:`All exercises pass. Explain a solution without looking, then try a new edge case. ${s.reviewed} of 3 code reviews completed.`;}
  function list(){const visible=exercises.filter(q=>q.area===area&&(language==='all'||q.lang===language));$('workshop-exercises').innerHTML=visible.length?visible.map(q=>{const e=state.entries[q.id];return `<button type="button" data-exercise="${q.id}" aria-current="${q.id===state.selected}">${esc(q.title)}<small>${esc(q.lang)} · ${e.reviewed?'Reviewed':core.passed(e)?e.solutionUsed?'Passing · solution used':'Passing':'To practice'}</small></button>`;}).join(''):'<p>No exercises in this language here. Choose All languages or another area.</p>';}
  function stop(){runVersion++;runner.cancel();const run=$('workshop-run'),stopButton=$('workshop-stop');if(run)run.disabled=false;if(stopButton)stopButton.disabled=true;}
  function setStatus(text,status=''){$('workshop-status').textContent=text;$('workshop-status').dataset.state=status;}
  function projectGuide(){return `<details class="workshop-project-guide"><summary>Build the full React app on Windows · setup + three milestones</summary><p>Practice the helper functions below, then use them in a real task manager. The browser tests use fixed API responses. The downloaded React app makes real requests to your local REST server.</p><a href="downloads/react-task-manager.zip" download>Download React task manager starter (.zip) ↓</a><div class="workshop-project-flow" aria-label="React on port 5173 calls the Vite development proxy, which forwards API requests to Express on port 3001"><span>React UI<br />localhost:5173</span><b>→</b><span>Vite /api proxy</span><b>→</b><span>Express REST<br />localhost:3001</span></div><ol><li>Finish <a href="#windows-rest">Windows REST</a> first. Keep its server running in one terminal. Install Node.js 24 LTS if you have not already.</li><li>Extract the ZIP. In File Explorer open the extracted folder that contains <code>package.json</code>. Type <code>powershell</code> in its address bar and press Enter.</li><li>In this second terminal run:<pre><code>npm.cmd install\nnpm.cmd run dev</code></pre>Open <code>http://127.0.0.1:5173</code>. Keep both terminals open. Stop each with Ctrl+C when finished.</li><li>Edit <code>src/helpers.js</code> in your editor. Complete the three milestones below: title validation, filtering, and safe API loading. Transfer your passing functions into that file, keeping <code>export</code> before each function.</li></ol><h4>Manual acceptance checklist</h4><ul><li>Add, complete, and delete a task. Reload and confirm the API still holds it (server restart clears its in-memory data).</li><li>Try a blank title, extra spaces, and a title over 120 characters. Reject invalid values before sending a request.</li><li>Switch All / Open / Done. Confirm your source task list is unchanged.</li><li>Stop the REST server, then click Refresh. Show a helpful error and allow retry. Restart it and refresh again.</li><li>Use browser DevTools network throttling to observe the loading state and disabled submit button during a request.</li></ul><p>Connection error? Check port 3001, both terminal windows, and <code>vite.config.js</code>. The development proxy avoids browser cross-origin requests; it is not a production API deployment. Read the included README for the walkthrough.</p></details>`;}
  function render(){
    stop();const q=selected(),e=state.entries[q.id];area=q.area;
    $('workshop-areas').innerHTML=areas.map(a=>`<button type="button" data-area="${a.id}" aria-pressed="${a.id===area}">${esc(a.title)}</button>`).join('');$('workshop-area-description').textContent=areas.find(a=>a.id===area).description;list();
    const fixtures=q.lang==='javascript'&&/fetch\(/.test(q.solution);
    $('workshop-exercise').innerHTML=`<div class="section-kicker">${esc(q.lang)} · ${esc(q.level||'Practice')}</div><h3>${esc(q.title)}</h3><p>${esc(q.lesson)}</p><div class="workshop-brief"><b>Your task</b><p>${esc(q.prompt)}</p></div>${q.area==='projects'?projectGuide():''}${q.lang==='sql'?`<details><summary>Database schema and seed data · view before querying</summary><p>devices.id → events.device_id is a one-to-many relationship. The database resets on every run. Query freely; your other exercises stay unchanged.</p><pre><code>${esc(schema)}</code></pre></details>`:''}${q.tests?`<details><summary>Test cases · inputs and expected results (${q.tests.length})</summary>${q.tests.map(t=>`<div class="workshop-test"><b>${esc(t.name)}</b><code>Input: ${esc(JSON.stringify(t.args))}\nExpected: ${esc(JSON.stringify(t.expected))}</code></div>`).join('')}</details>`:''}<label for="workshop-code">${q.lang==='sql'?'Your SQL query':'Your code'} · ${q.lang==='python'?'indent with 4 spaces':'edit the starter below'}</label><textarea class="workshop-code" id="workshop-code" spellcheck="false" autocapitalize="off" autocomplete="off" maxlength="20000" aria-describedby="workshop-runtime-note"></textarea><div class="workshop-actions"><button class="primary-button" id="workshop-run" type="button">${q.lang==='sql'?'Run query + check':'Run tests'} →</button><button class="secondary-button" id="workshop-stop" type="button" disabled>Stop</button><button class="quiet-button" id="workshop-reset" type="button">Restore starter</button></div><p class="workshop-notice" id="workshop-runtime-note">Code runs in an isolated worker with a 5-second execution limit. ${q.lang==='javascript'?'JavaScript runs in your browser.':q.lang==='python'?'Python uses Pyodide; the first runtime download can take up to 90 seconds. Internet access is required to load it.':'SQLite runs in your browser using sql.js. Internet access is required to load the runtime.'}${fixtures?' fetch is a local test fixture, not a live API call.':''}</p><div class="workshop-status" id="workshop-status" role="status" aria-live="polite"></div><div id="workshop-results"></div><details><summary>Hint 1 · a nudge</summary><p>${esc(q.hints[0])}</p></details><details><summary>Hint 2 · a concrete next step</summary><p>${esc(q.hints[1])}</p></details><details id="workshop-solution"><summary>Worked solution · try the tests first</summary><pre><code>${esc(q.solution)}</code></pre><p>${esc(q.explain)}</p><button class="secondary-button" id="workshop-use-solution" type="button">Replace editor with solution</button><p class="workshop-notice">Using this button labels the exercise “solution used.” Passing tests checks these examples, not complete interview mastery.</p></details>${q.review?`<div class="workshop-review"><h4>Explain your review</h4><p>What was wrong, which test revealed it, and what tradeoff remains? This is self-review; your written answer is not automatically graded.</p><label for="workshop-review-notes">Your explanation · at least 30 characters</label><textarea id="workshop-review-notes" maxlength="6000"></textarea>${q.review.map((label,i)=>`<label><input type="checkbox" data-review-check="${i}" ${e.checks[i]?'checked':''} />${esc(label)}</label>`).join('')}<button type="button" class="primary-button workshop-save-review" id="workshop-save-review">Mark review complete</button><p id="workshop-review-status" role="status"></p></div>`:''}<p class="workshop-references">Read more: ${q.lang==='python'?'<a href="https://docs.python.org/3/tutorial/" target="_blank" rel="noopener">Python tutorial ↗</a>':q.lang==='sql'?'<a href="https://www.sqlite.org/lang_select.html" target="_blank" rel="noopener">SQLite SELECT ↗</a>':'<a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide" target="_blank" rel="noopener">JavaScript guide ↗</a>'}</p>`;
    $('workshop-code').value=e.code;if(q.review){$('workshop-review-notes').value=e.notes;$('workshop-review-status').textContent=e.reviewed?'Review completed.':'Pass the code tests, write your explanation, then check each review criterion.';}
    setStatus(core.passed(e)?`All tests passed for this saved code.${e.solutionUsed?' Worked solution used.':''}`:'Ready. Run the starter to see which cases need work.',core.passed(e)?'pass':'');stats();
  }
  $('workshop-areas').addEventListener('click',event=>{const b=event.target.closest('[data-area]');if(!b)return;area=b.dataset.area;language='all';$('workshop-language').value='all';state.selected=exercises.find(q=>q.area===area&&!core.passed(state.entries[q.id]))?.id||exercises.find(q=>q.area===area).id;save();render();});
  $('workshop-exercises').addEventListener('click',event=>{const b=event.target.closest('[data-exercise]');if(!b)return;state.selected=b.dataset.exercise;save();render();});
  $('workshop-language').addEventListener('change',event=>{language=event.target.value;const next=exercises.find(q=>q.area===area&&(language==='all'||q.lang===language));if(next){state.selected=next.id;save();render();}else list();});
  $('workshop-exercise').addEventListener('input',event=>{
    const e=state.entries[state.selected];
    if(event.target.id==='workshop-code'){
      stop();core.edit(e,event.target.value);$('workshop-results').replaceChildren();setStatus('Code changed. Run tests to check this version.');
      if($('workshop-review-status'))$('workshop-review-status').textContent='Code changed. Pass its tests and mark the review complete again.';
      save();list();
    }
    if(event.target.id==='workshop-review-notes'){e.notes=event.target.value;e.reviewed=false;save();$('workshop-review-status').textContent='Explanation changed. Mark the review complete again when ready.';}
  });
  $('workshop-exercise').addEventListener('change',event=>{if(event.target.matches('[data-review-check]')){const e=state.entries[state.selected];e.checks[Number(event.target.dataset.reviewCheck)]=event.target.checked;e.reviewed=false;save();$('workshop-review-status').textContent='Review checklist updated.';}});
  $('workshop-exercise').addEventListener('click',async event=>{
    const id=event.target.closest('button')?.id,q=selected(),e=state.entries[q.id];
    if(id==='workshop-stop'){stop();setStatus('Stopped. Edit your code or run again.');}
    if(id==='workshop-reset'||id==='workshop-use-solution'){core.edit(e,id==='workshop-reset'?q.starter:q.solution);e.solutionUsed=id==='workshop-use-solution';save();render();}
    if(id==='workshop-save-review'){e.reviewed=core.canReview(e);save();list();$('workshop-review-status').textContent=e.reviewed?'Review completed. Try explaining the fix aloud.':'First pass all tests with your current code, write at least 30 characters, and check every criterion.';}
    if(id!=='workshop-run')return;
    stop();const version=runVersion,snapshot=e.code;$('workshop-run').disabled=true;$('workshop-stop').disabled=false;$('workshop-results').replaceChildren();
    const result=await runner.run({lang:q.lang,code:snapshot,fn:q.fn,tests:q.tests,expected:q.expected,schema},text=>{if(version===runVersion)setStatus(text);});
    if(version!==runVersion)return;$('workshop-run').disabled=false;$('workshop-stop').disabled=true;
    if(result.cancelled){setStatus('Run stopped. Try again when ready.');return;}
    const passed=core.grade(e,snapshot,result,q);save();list();setStatus(result.error||`${result.tests.filter(t=>t.passed).length} / ${result.tests.length} tests passed.${passed?' Explain why your solution works.':' Compare the actual result with the expected result below.'}${e.solutionUsed?' Worked solution used.':''}`,passed?'pass':'fail');
    $('workshop-results').innerHTML=(result.tables||[]).map(t=>`<div class="workshop-table-wrap"><table><thead><tr>${t.columns.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${t.values.map(row=>`<tr>${row.map(v=>`<td>${esc(v===null?'NULL':v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('')+(result.tables?.length?'<p class="workshop-notice">Showing up to 3 result tables, 100 rows, and 20 columns per table.</p>':'')+(result.tests||[]).map(t=>`<div class="workshop-test" data-pass="${t.passed===true}"><b>${t.passed?'✓ Pass':'↳ Try again'} · ${esc(t.name)}</b><code>Expected: ${esc(t.expected)}\nActual: ${esc(t.actual)}</code></div>`).join('')+(result.logs?.length?`<h4>Console output</h4><pre><code>${esc(result.logs.join('\n'))}</code></pre>`:'');
  });
  window.addEventListener('hashchange',()=>{if(location.hash!=='#workshop'){stop();if($('workshop-status'))setStatus(core.passed(state.entries[state.selected])?'Saved code has passed its tests.':'Ready. Run tests when you return.');}});
  render();save();
})();
